const _ = require('lodash');
const co = require('co');

const DCache = require('@taf/taf-dcache-helper');

const _key = require('./data_structures/key');
const _string = require('./data_structures/string');
const _hash = require('./data_structures/hash');
const _list = require('./data_structures/list');
const _set = require('./data_structures/set');
const _sortedset = require('./data_structures/sortedset');
const _origin = require('./data_structures/origin');

const _extend = require('./data_structures/extend');

const constant = require('./lib/constant');
const common = require('./lib/common');
const cache = require('./lib/cache');

/**
 * Created by easonzhu on 2017/7/13.
 *
 * TODO more data structure
 * TODO more data operation
 * TODO error handle
 *
 */
const buildDCache = (target, module) => {
  return new DCache({
    DCacheServerTarget: target,
    moduleName: module,
    keepAlive: true,
    heartInterval: 30000,
  });
};

const CONSTANT = {

  TYPE: constant.TYPE,

  DIRECTION: constant.DIRECTION,

  CONSTANT: constant.CONSTANT,

  ERROR: constant.ERROR,

};

const data_structures = [ _key, _string, _hash, _list, _set, _sortedset, _extend, _origin ];

module.exports = (target, module, retry) => {

  // build DCache
  const DCache = buildDCache(target, module);

  // build CacheHelper
  const Cache = cache(DCache);

  // build common
  const Common = common(Cache, module, retry || constant.RETRY);

  /*
   * export constant and operation of data structures
   */
  const OPERATION = {};
  data_structures.forEach(struct => {
    const instance = struct(Common);
    for (const operation in instance) {
      const fn = instance[operation];
      if (_.isFunction(fn)) {
        OPERATION[operation] = fn;
      }
    }
  });

  return _.assign(OPERATION, CONSTANT, {
    toPromise: function() {
      for (const operation in OPERATION) {
        const fn = OPERATION[operation];
        if (_.isFunction(fn)) {
          OPERATION[operation] = co.wrap(fn);
        }
        delete OPERATION.toPromise;
      }
      return OPERATION;
    },
  });

};
